package game.ui;

import game.model.Item;

import javax.imageio.ImageIO;
import javax.swing.*;
import java.awt.*;
import java.awt.image.BufferedImage;
import java.io.InputStream;
import java.util.HashMap;
import java.util.Map;

/**
 * Pencil-drawn icons for items (images/items/{icon}.png) and augment categories
 * (images/augments/{key}.png), generated by tools/pencil-art. Scaled copies are cached per size.
 */
public final class ItemArt {
    private static final Map<String, BufferedImage> SOURCES = new HashMap<>();
    private static final Map<String, ImageIcon> SCALED = new HashMap<>();

    private ItemArt() {}

    /** The item's icon at size x size, or null if it has none. */
    public static ImageIcon item(Item item, int size) {
        return item == null || item.getIcon() == null ? null : scaled("images/items/" + item.getIcon() + ".png", size);
    }

    /** A non-item picture from the same folder (treasure chests, quest scroll, inn bed). */
    public static ImageIcon misc(String key, int size) {
        return scaled("images/items/" + key + ".png", size);
    }

    public static ImageIcon augment(String key, int size) {
        return scaled("images/augments/" + key + ".png", size);
    }

    private static ImageIcon scaled(String path, int size) {
        String key = path + "@" + size;
        if (SCALED.containsKey(key)) return SCALED.get(key);
        BufferedImage src = SOURCES.computeIfAbsent(path, ItemArt::load);
        ImageIcon icon = src == null ? null : new ImageIcon(shrink(src, size));
        SCALED.put(key, icon);
        return icon;
    }

    /** Halves step by step before the last bilinear pass, so thin pencil lines stay visible. */
    private static BufferedImage shrink(BufferedImage src, int size) {
        BufferedImage cur = src;
        while (cur.getWidth() / 2 >= size) cur = resize(cur, cur.getWidth() / 2);
        return resize(cur, size);
    }

    private static BufferedImage resize(BufferedImage src, int size) {
        BufferedImage out = new BufferedImage(size, size, BufferedImage.TYPE_INT_ARGB);
        Graphics2D g = out.createGraphics();
        g.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BILINEAR);
        g.drawImage(src, 0, 0, size, size, null);
        g.dispose();
        return out;
    }

    private static BufferedImage load(String path) {
        try (InputStream in = ItemArt.class.getResourceAsStream(path)) {
            if (in != null) return ImageIO.read(in);
        } catch (Exception ignored) {
            // Missing icon: callers show the text without it.
        }
        return null;
    }
}
